commands.command:
set -euo pipefail
test "$(uname -s)" = Darwin
BASE=ceb234ace7050abb35964cef467266681e29b574
test "$(git rev-parse HEAD)" = "$BASE"
test -z "$(git status --porcelain)"
export GIT_TERMINAL_PROMPT=0
WORK="$(mktemp -d /tmp/bloomml-m05.XXXXXX)"
git clone --quiet --branch main https://github.com/MichalMatu/bloomml.git "$WORK/source"
cd "$WORK/source"
test "$(git rev-parse HEAD)" = "$BASE"
echo "M05_WORK|$WORK/source"
python3 - <<'PY'
from pathlib import Path
def rep(path,old,new):
    p=Path(path); s=p.read_text(); assert s.count(old)==1,(path,s.count(old)); p.write_text(s.replace(old,new))
p='lib/environment_control/src/climate/ClimatePolicy.cpp'
rep(p,'''  if (input.targets.co2_enabled && input.capabilities.co2_doser &&
      usable(measurements.co2_ppm, input.sensor_timeout_ms)) {
    const float co2_error = input.targets.co2_ppm - measurements.co2_ppm.value;
    if (co2_error > kCo2DeadbandPpm) {
      request.co2_doser = level(co2_error, kCo2DeadbandPpm, kCo2FullScalePpm);
    }
  }''','''  if (input.targets.co2_enabled && std::isfinite(input.targets.co2_ppm) &&
      input.targets.co2_ppm > 0.0F && usable(measurements.co2_ppm, input.sensor_timeout_ms)) {
    const float co2_error = input.targets.co2_ppm - measurements.co2_ppm.value;
    if (co2_error > kCo2DeadbandPpm && input.capabilities.co2_doser) {
      request.co2_doser = level(co2_error, kCo2DeadbandPpm, kCo2FullScalePpm);
    } else if (co2_error < -kCo2DeadbandPpm && input.capabilities.exhaust_fan &&
               measurements.co2_ppm.value < kMaximumCo2Ppm) {
      // A ventilation request is a conditional means of dilution, not a
      // prediction of outdoor CO2 or proof of physical concentration change.
      // At the emergency threshold the independent safety stage owns the override.
      request.exhaust_fan = std::max(
          request.exhaust_fan, level(co2_error, kCo2DeadbandPpm, kCo2FullScalePpm));
    }
  }''')
p='test/test_climate_runtime_parity/test_main.cpp'
rep(p,'} // namespace\n\nint main() {','''void testCo2TargetVentilation() {
  using namespace growbox::climate;
  ClimateControllerInput input{};
  auto& m = input.state.measurements;
  m.air_temperature_c = {24.0F, true, 0U};
  m.relative_humidity_pct = {60.0F, true, 0U};
  input.targets.air_temperature_c = 24.0F;
  input.targets.relative_humidity_pct = 60.0F;
  input.targets.co2_enabled = true;
  input.targets.co2_ppm = 900.0F;
  input.capabilities.exhaust_fan = true;
  input.capabilities.co2_doser = true;
  struct Scenario {
    const char* name;
    float ppm;
    bool fresh;
    bool enabled;
    bool fan;
    bool doser;
    float expected_fan;
    float expected_doser;
  };
  const Scenario scenarios[] = {
      {"CO2 excess below safety", 1200.0F, true, true, true, true, 0.5F, 0.0F},
      {"CO2 high without doser", 1200.0F, true, true, true, false, 0.5F, 0.0F},
      {"CO2 no fan", 1200.0F, true, true, false, true, 0.0F, 0.0F},
      {"CO2 deadband", 950.0F, true, true, true, true, 0.0F, 0.0F},
      {"CO2 deficit", 600.0F, true, true, true, true, 0.0F, 0.5F},
      {"CO2 stale", 1200.0F, false, true, true, true, 0.0F, 0.0F},
      {"CO2 disabled", 1200.0F, true, false, true, true, 0.0F, 0.0F},
      {"CO2 safety independent", 1800.0F, true, false, true, true, 1.0F, 0.0F},
  };
  for (const auto& s : scenarios) {
    m.co2_ppm = {s.ppm, true, s.fresh ? 0U : input.sensor_timeout_ms + 1U};
    input.targets.co2_enabled = s.enabled;
    input.capabilities.exhaust_fan = s.fan;
    input.capabilities.co2_doser = s.doser;
    ClimateRuntimeController runtime{nullptr, {}};
    ClimateRuntimeDecision decision{};
    runtime.step(input, 1000U, decision);
    check(near(decision.rule.safe.exhaust_fan, s.expected_fan), s.name, "ventilation");
    check(near(decision.rule.safe.co2_doser, s.expected_doser), s.name, "dosing");
  }
}
} // namespace

int main() {
  testCo2TargetVentilation();''')
PY
git diff --check
git diff --stat
make test-host > "$WORK/stage1-host.log" 2>&1 || { tail -n 100 "$WORK/stage1-host.log"; exit 1; }
grep -E 'tests passed|Total Test time' "$WORK/stage1-host.log"
python3 scripts/check_runtime_boundaries.py
python3 scripts/check_output_rf_ownership.py
python3 scripts/check_runtime_config_ssot.py
git add lib/environment_control/src/climate/ClimatePolicy.cpp test/test_climate_runtime_parity/test_main.cpp
git diff --cached --check
git commit -m "feat(climate): request ventilation for CO2 above the user target"
test -z "$(git status --porcelain)"
echo "M05_STAGE1_LOCAL_SHA|$(git rev-parse HEAD)"
echo M05_STAGE1_PASS_NO_PUSH
